import{_ as t,o,c as a,a2 as e}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"通用","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/general.md","filePath":"zh-TW/user-guide/settings/general.md","lastUpdated":1785993908000}'),s={name:"zh-TW/user-guide/settings/general.md"};function n(i,r,l,g,h,p){return o(),a("div",null,[...r[0]||(r[0]=[e('<h1 id="通用" tabindex="-1">通用 <a class="header-anchor" href="#通用" aria-label="Permalink to &quot;通用&quot;">​</a></h1><p>六個分頁:<strong>系統</strong>、<strong>快速搜尋視窗</strong>、<strong>完整搜尋視窗</strong>、<strong>預覽視窗</strong>、<strong>快速導覽</strong>、<strong>預覽與縮圖</strong>。</p><h2 id="系統" tabindex="-1">系統 <a class="header-anchor" href="#系統" aria-label="Permalink to &quot;系統&quot;">​</a></h2><ul><li><strong>開機自動啟動 Lertaro</strong> —— 核取方塊，登入時自動啟動。</li><li><strong>啟動時自動檢查更新</strong> —— 核取方塊。</li><li><strong>自動靜默更新</strong> —— 核取方塊，僅在上面的選項開啟時可用；偵測到新版本時在背景靜默下載安裝，不彈出視窗提示。</li><li><strong>啟用硬體加速</strong> —— 核取方塊，預設開啟。關閉後會讓快速搜尋視窗改用軟體轉譯而不是 Direct3D—— 用來解決 NVIDIA Advanced Optimus 因為 Lertaro 在執行而拒絕切換顯示卡的問題(只影響快速視窗，不影響整個 App)。需要重新啟動 Lertaro 才能生效。</li><li><strong>隱藏系統匣圖示</strong> —— 核取方塊，預設關閉。立即生效，不需要重新啟動。不管這個設定開不開，<a href="./../hotkeys.html#搜尋框圖示">快速視窗自帶的圖示</a>始終能開啟和系統匣圖示右鍵一樣的選單，所以隱藏系統匣圖示不會讓你找不到設定或結束的入口。</li><li><strong>啟用模糊比對</strong> —— 核取方塊，預設開啟。開啟時，一般查詢詞只要字元按順序出現在名稱中任意位置就能命中；關閉後，一般查詢詞必須作為連續子字串出現(<code>abc</code> 不再符合 <code>a-b-c</code>)——哪些不受影響見<a href="./../search-syntax.html#模糊比對-預設">搜尋語法</a>。立即生效，不需要重新啟動。</li><li><strong>查詢標記總前導字元</strong> —— 文本框（最多 1 個字元，預設為 <code>:</code>）。設定搜尋框尾部切分標記運算式的總前導字元。動態路徑過濾與自訂分類過濾外掛前綴可在 <strong>設定 → 外掛 → CoreExtensions</strong> 中獨立設定。</li><li><strong>記錄層級</strong> —— 下拉式選單:錯誤 / 警告 / 資訊(預設)/ 偵錯。控制 App、Service、Hook 三處記錄 (見<a href="./service-status.html">執行狀態</a>)的詳細程度。</li><li><strong>介面語言</strong> —— 下拉式選單，內容來自所有已安裝的語言包提供者(內建語言加上任何外掛新增的語言)。</li></ul><p>佈景主題選擇已經移到獨立的<a href="./appearance.html">外觀</a>分區——佈景主題選擇器和「跟隨系統淺色/深色設定」選項都在那一頁。</p><h2 id="快速搜尋視窗" tabindex="-1">快速搜尋視窗 <a class="header-anchor" href="#快速搜尋視窗" aria-label="Permalink to &quot;快速搜尋視窗&quot;">​</a></h2><p>涵蓋快速搜尋列的外觀版面配置，以及它搜尋結果的類型優先權。</p><p><strong>搜尋列版面配置</strong> —— 自訂快速搜尋列的大小以及螢幕顯示位置:</p><ul><li><strong>搜尋列寬度(像素)</strong> —— 範圍 300–1200px，預設 570px。</li><li><strong>搜尋列高度(像素)</strong> —— 範圍 45–120px，預設 60px。這一個數值同時驅動結果列的圖示大小、名稱/ 路徑字型大小和行高(<code>高度 / 60</code>)，所以搜尋列調高，整個結果清單也會跟著放大，圖示和文字始終保持同樣的比例。</li><li><strong>搜尋框內顯示時鐘</strong> —— 核取方塊，預設關閉。開啟後，當搜尋框為空時會用目前日期、星期幾和時間替換掉原本的「輸入以搜尋...」提示文字。一開始輸入內容，時鐘就會和提示文字一樣消失。只影響快速視窗——內嵌視窗不管這個設定開沒開，都保持它自己原本的提示文字。</li><li><strong>再次按下快捷鍵時開啟完整視窗</strong> —— 核取方塊，預設關閉。正常情況下，快速視窗已經開啟時再按一次叫出熱鍵只會隱藏它；開啟這個選項後，第二次按下會改為切換到完整視窗(帶上已經輸入的查詢內容)，而不是直接關閉。</li><li><strong>鎖定位置</strong> —— 核取方塊，預設關閉。開啟後不允許拖曳快速視窗，避免誤按把它挪離你放好的位置。按右鍵點擊 logo 仍然可以重設位置；下面的<strong>重設版面配置設定</strong>也會連同這個鎖一起清掉。</li><li><strong>重設版面配置設定</strong> 按鈕 —— 把以上五項都恢復為預設值。</li></ul><p>在<a href="./../hotkeys.html#搜尋框圖示">快速視窗的圖示</a>上按右鍵，可以單獨重設它的螢幕位置(不影響大小)，效果和首次啟動時的置中方式一樣。</p><p><strong>結果類型優先權</strong> —— 跟下面<a href="#快速導覽">快速導覽</a>同一套上移/下移(也可以拖曳)排序清單：把某個結果類型(應用程式、系統設定、檔案篩選器、任何第三方外掛自己提供的可搜尋項目，或內建的「檔案」項目)上移，就能讓它在快速視窗的結果裡始終排在下面的類型前面，不管實際上誰的文字比對得更好。歷史記錄和我的最愛始終排最前，不受這個清單影響。</p><p>每個類型還可以單獨設一個單字元<strong>觸發符</strong>(可選，每行一個輸入框)：在快速視窗裡把這個字元打在最前面，就只會顯示這個類型的結果，其他全部隱藏——具體範例見<a href="./../search-syntax.html#結果類型觸發符">搜尋語法</a>。只打觸發符、後面還沒打內容時，會顯示「繼續輸入以只搜尋……」這樣的提示，而不是「無搜尋結果」。挑一個平時正常搜尋絕對不會以它開頭的字元，因為一旦分配給某個類型，這個字元就等於被佔用了——建議用標點符號(比如 <code>;</code>)而不是純空格，因為只打一個空格、後面沒有內容時會被當成搜尋框為空處理，不會顯示這個提示。</p><h2 id="完整搜尋視窗" tabindex="-1">完整搜尋視窗 <a class="header-anchor" href="#完整搜尋視窗" aria-label="Permalink to &quot;完整搜尋視窗&quot;">​</a></h2><p>設定完整/主搜尋視窗(從工作列或開始功能表捷徑開啟的那個更大的視窗，區別於快速彈出搜尋列——見<a href="./../getting-started.html#三種視窗">快速上手</a>)的預設大小:</p><ul><li><strong>視窗寬度(像素)</strong> —— 範圍 640–2000px，預設 854px。</li><li><strong>視窗高度(像素)</strong> —— 範圍 400–1400px，預設 480px。這兩個下限分別對應視窗自身可拖曳調整的最小尺寸，所以設定的值不會被視窗自己悄悄覆蓋。</li><li><strong>重設搜尋視窗設定</strong> 按鈕。</li></ul><p>手動拖曳視窗邊緣調整大小時會自動記住這個尺寸——下次開啟視窗(或新開一個)時會沿用上次離開時的大小，本頁面上的數值也會同步更新。在視窗處於最大化狀態時調整不會覆蓋已記住的尺寸，只有在正常(非最大化)狀態下調整才會被記住。</p><p><strong>結果表格欄順序</strong> —— 跟設定裡其它地方(見<a href="./favorites.html">我的最愛</a>)同一套排序清單：把結果表格裡的某一欄(名稱、路徑、修改時間，或任何外掛新增的欄)左移或右移。只影響表格檢視的結果清單——精簡清單檢視裡沒有欄可以排序。</p><p><strong>側邊欄篩選順序</strong> —— 同樣的機制，調整側邊欄篩選分組(類型、修改時間，以及任何外掛新增的分組) 的先後順序。</p><p><strong>動作選單分組順序</strong> —— 同樣的機制，調整<a href="./../actions-and-preview.html#動作選單">動作選單</a>裡各個分組的先後順序：內建動作分組，以及每個往動作選單裡貢獻內容的外掛各一個分組(比如自訂動作，或 Windows 系統的右鍵選單)。還沒加入這個清單的分組會按自然順序排列(內建分組在前，外掛分組按各自貢獻的先後順序排在後面)。</p><p>點擊結果表格的欄標題排序會在三種狀態間循環:遞增、遞減，第三次點擊會重設回預設的相關性排序(表頭上的排序箭頭也會消失)。這個排序只在 Lertaro 執行期間有效——結束應用程式(不只是關閉視窗)後下次開啟會恢復預設排序，跟上面永久儲存的欄/側邊欄順序不一樣。</p><h2 id="預覽視窗" tabindex="-1">預覽視窗 <a class="header-anchor" href="#預覽視窗" aria-label="Permalink to &quot;預覽視窗&quot;">​</a></h2><ul><li><strong>預覽視窗寬度(像素)</strong> —— 範圍 250–900px。</li><li><strong>預覽視窗高度(像素)</strong> —— 範圍 250–1200px，預設值不會在常見顯示器上顯得過高。</li><li><strong>重設預覽視窗設定</strong> 按鈕。</li></ul><p>預覽視窗的尺寸是固定的，不受目前結果數量影響——它不是一個隨內容變化的自適應大小。預覽面板具體如何定位，見<a href="./../actions-and-preview.html">動作選單與預覽</a>。</p><h2 id="快速導覽" tabindex="-1">快速導覽 <a class="header-anchor" href="#快速導覽" aria-label="Permalink to &quot;快速導覽&quot;">​</a></h2><p>設定<a href="./../hotkeys.html#快速導覽-滑鼠">快速導覽</a>選單根層級各個分組的先後順序——每個貢獻項目的 provider 一個分組(比如我的最愛/歷史記錄/設定好的捷徑資料夾、Total Commander 的 Directory Hotlist、Directory Opus 的我的最愛、某個外掛自己的快速導覽項目)，各自帶一個標題。</p><p><strong>提供者順序</strong> —— 跟設定裡其它地方(見<a href="./favorites.html">我的最愛</a>)同一套上移/下移(也可以拖曳)排序清單：把某個 provider 上移或下移，就能改變它的分組相對其它分組出現的位置。這裡只列出外掛元件目前處於啟用狀態的 provider——在<a href="./plugins.html">外掛</a>裡整體停用的元件從一開始就不會成為選單候選項，也就沒有順序可調。</p><h2 id="預覽與縮圖" tabindex="-1">預覽與縮圖 <a class="header-anchor" href="#預覽與縮圖" aria-label="Permalink to &quot;預覽與縮圖&quot;">​</a></h2><p>兩個各自獨立的優先權排序清單，分別決定各自領域裡哪個提供者優先被嘗試——正常情況下完全由每個提供者自身固定的內建優先權決定，除了整體停用某個提供者以外，沒有別的辦法能改變這個順序。</p><p><strong>檔案預覽提供者順序</strong> —— 針對<a href="./../actions-and-preview.html#quicklook-預覽">檔案預覽提供者</a>(比如 <a href="./../actions-and-preview.html#透過-quicklook-的外部預覽-可選">QuickLook Bridge</a>外掛會把自己的優先權設得比所有內建預覽類型都高)。跟設定裡其它地方(見<a href="./favorites.html">我的最愛</a>)同一套上移/下移(也可以拖曳)排序清單：把某個提供者上移，就能讓它始終優先於排在它下面的提供者，不管它自己內建的優先權是多少。這裡只列出外掛元件目前處於啟用狀態的提供者——在<a href="./plugins.html">外掛</a>裡整體停用的元件反正也不會真正參與任何預覽。</p><p><strong>縮圖提供者順序</strong> —— 同樣的機制，針對的是結果清單本身顯示的圖示/縮圖(而不是預覽面板)—— 目前內建的提供者只有一個，等以後有多個外掛都實作了自訂縮圖提供者時，這個順序才真正有意義。</p>',30)])])}const u=t(s,[["render",n]]);export{c as __pageData,u as default};
